import AVFoundation
import CryptoKit
import Foundation
import Security

struct Chunk: Codable {
    let id: UUID
    let startedAt: Date
    let duration: Double
    let sha256: String
    var name: String { id.uuidString.lowercased() }
    var audioURL: URL { QueueStore.directory.appendingPathComponent(name + ".m4a") }
    var manifestURL: URL { QueueStore.directory.appendingPathComponent(name + ".json") }
}

struct RecordingJournal: Codable {
    let id: UUID
    let startedAt: Date
}

enum QueueStore {
    static let directory: URL = {
        let support = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        let url = support.appendingPathComponent("PendingAudio", isDirectory: true)
        try! FileManager.default.createDirectory(at: url, withIntermediateDirectories: true,
            attributes: [.protectionKey: FileProtectionType.completeUntilFirstUserAuthentication])
        var values = URLResourceValues()
        values.isExcludedFromBackup = true
        var excludedURL = url
        try? excludedURL.setResourceValues(values)
        return url
    }()

    static var deviceID: String {
        if let value = UserDefaults.standard.string(forKey: "deviceID") { return value }
        let value = UUID().uuidString.lowercased()
        UserDefaults.standard.set(value, forKey: "deviceID")
        return value
    }

    static func pending() -> [Chunk] {
        let files = (try? FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)) ?? []
        return files.filter { $0.pathExtension == "json" && !$0.lastPathComponent.contains(".recording.") }
            .compactMap { try? JSONDecoder().decode(Chunk.self, from: Data(contentsOf: $0)) }
            .sorted { $0.startedAt < $1.startedAt }
    }

    static func checksum(_ url: URL) throws -> String {
        let handle = try FileHandle(forReadingFrom: url)
        defer { try? handle.close() }
        var hash = SHA256()
        while let data = try handle.read(upToCount: 65536), !data.isEmpty { hash.update(data: data) }
        return hash.finalize().map { String(format: "%02x", $0) }.joined()
    }

    static func seal(_ journal: RecordingJournal, duration: Double) throws -> Chunk {
        let name = journal.id.uuidString.lowercased()
        let audio = directory.appendingPathComponent(name + ".m4a")
        let chunk = Chunk(id: journal.id, startedAt: journal.startedAt, duration: duration,
                          sha256: try checksum(audio))
        try JSONEncoder().encode(chunk).write(to: chunk.manifestURL, options: .atomic)
        try? FileManager.default.removeItem(at: directory.appendingPathComponent(name + ".recording.json"))
        return chunk
    }

    static func recoverInterruptedFiles() async -> Int {
        let files = (try? FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)) ?? []
        var unrecoverable = 0
        for file in files where file.lastPathComponent.hasSuffix(".recording.json") {
            do {
                let journal = try JSONDecoder().decode(RecordingJournal.self, from: Data(contentsOf: file))
                let audio = directory.appendingPathComponent(journal.id.uuidString.lowercased() + ".m4a")
                let duration = try await AVURLAsset(url: audio).load(.duration).seconds
                guard duration.isFinite && duration > 0 else { unrecoverable += 1; continue }
                _ = try seal(journal, duration: duration)
            } catch {
                // Keep an incomplete file for recovery; never pretend it was uploaded.
                unrecoverable += 1
            }
        }
        // Removal of an acknowledged manifest is the local commit point. Finish cleanup after a crash.
        for audio in files where audio.pathExtension == "m4a" {
            let stem = audio.deletingPathExtension().lastPathComponent
            if !FileManager.default.fileExists(atPath: directory.appendingPathComponent(stem + ".json").path)
                && !FileManager.default.fileExists(atPath: directory.appendingPathComponent(stem + ".recording.json").path) {
                try? FileManager.default.removeItem(at: audio)
            }
        }
        return unrecoverable
    }

    static func removeAcknowledged(_ chunk: Chunk) throws {
        // Only called after a verified durable receipt. Commit dequeue before deleting its audio.
        try FileManager.default.removeItem(at: chunk.manifestURL)
        if FileManager.default.fileExists(atPath: chunk.audioURL.path) {
            try FileManager.default.removeItem(at: chunk.audioURL)
        }
    }
}

enum Credentials {
    private static let service = "com.browseruse.liferecorder.receiver"
    static func token() -> String {
        let query: [String: Any] = [kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service, kSecAttrAccount as String: "token",
            kSecReturnData as String: true, kSecMatchLimit as String: kSecMatchLimitOne]
        var result: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &result) == errSecSuccess,
              let data = result as? Data else { return "" }
        return String(data: data, encoding: .utf8) ?? ""
    }
    static func setToken(_ token: String) throws {
        let query: [String: Any] = [kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service, kSecAttrAccount as String: "token"]
        let changes: [String: Any] = [kSecValueData as String: Data(token.utf8),
            kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly]
        var status = SecItemUpdate(query as CFDictionary, changes as CFDictionary)
        if status == errSecItemNotFound {
            status = SecItemAdd(query.merging(changes) { _, new in new } as CFDictionary, nil)
        }
        guard status == errSecSuccess else { throw NSError(domain: NSOSStatusErrorDomain, code: Int(status)) }
    }
}

struct ReceiverSettings {
    let baseURL: URL
    let token: String
    let certificateSHA256: String

    static func load() -> ReceiverSettings? {
        guard let raw = UserDefaults.standard.string(forKey: "receiverURL"),
              let url = URL(string: raw), url.scheme == "https", url.host != nil,
              url.user == nil, url.password == nil, url.query == nil, url.fragment == nil else { return nil }
        let token = [REDACTED]
        guard !token.isEmpty else { return nil }
        return ReceiverSettings(baseURL: url, token: token,
            certificateSHA256: UserDefaults.standard.string(forKey: "certificateSHA256") ?? "")
    }

    static func save(url: String, token: String, pin: String) throws {
        guard let parsed = URL(string: url.trimmingCharacters(in: .whitespacesAndNewlines)),
              parsed.scheme == "https", parsed.host != nil, parsed.user == nil, parsed.password == nil,
              parsed.query == nil, parsed.fragment == nil,
              parsed.path.isEmpty || parsed.path == "/", !token.isEmpty else {
            throw NSError(domain: "Settings", code: 1,
                userInfo: [NSLocalizedDescriptionKey: "Enter an HTTPS receiver address and its pairing token."])
        }
        let cleanPin = pin.lowercased().replacingOccurrences(of: ":", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard cleanPin.isEmpty || (cleanPin.count == 64 && cleanPin.allSatisfy { $0.isHexDigit }) else {
            throw NSError(domain: "Settings", code: 2,
                userInfo: [NSLocalizedDescriptionKey: "The certificate fingerprint must contain 64 hexadecimal characters."])
        }
        try Credentials.setToken(token)
        UserDefaults.standard.set(parsed.absoluteString, forKey: "receiverURL")
        UserDefaults.standard.set(cleanPin, forKey: "certificateSHA256")
    }
}

import AVFoundation
import XCTest
@testable import LifeRecorder

final class NativeUploadTests: XCTestCase {
    @MainActor
    func testPinnedHTTPSUploadRemovesOnlyAcknowledgedClip() async throws {
        let environment = ProcessInfo.processInfo.environment
        guard let address = environment["LIFE_TEST_URL"], let token = [REDACTED]"LIFE_TEST_TOKEN"],
              let pin = environment["LIFE_TEST_PIN"] else {
            throw XCTSkip("Set LIFE_TEST_URL, LIFE_TEST_TOKEN and LIFE_TEST_PIN for the isolated HTTPS test receiver")
        }
        // Never use a user-configured receiver for this integration test.
        guard address == "https://127.0.0.1:8766" else { throw XCTSkip("Expected isolated loopback test receiver") }
        let priorURL = UserDefaults.standard.string(forKey: "receiverURL")
        let priorPin = UserDefaults.standard.string(forKey: "certificateSHA256")
        let priorToken = [REDACTED]
        defer {
            UserDefaults.standard.set(priorURL, forKey: "receiverURL")
            UserDefaults.standard.set(priorPin, forKey: "certificateSHA256")
            try? Credentials.setToken(priorToken)
        }
        try ReceiverSettings.save(url: address, token: token, pin: pin)
        let journal = RecordingJournal(id: UUID(), startedAt: Date())
        let path = QueueStore.directory.appendingPathComponent(journal.id.uuidString.lowercased() + ".m4a")
        let format = AVAudioFormat(standardFormatWithSampleRate: 16000, channels: 1)!
        let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: 16000)!
        buffer.frameLength = 16000
        for i in 0..<16000 { buffer.floatChannelData![0][i] = Float(sin(Double(i) * 2 * .pi * 440 / 16000)) * 0.1 }
        var file: AVAudioFile? = try AVAudioFile(forWriting: path, settings: [
            AVFormatIDKey: kAudioFormatMPEG4AAC, AVSampleRateKey: 16000,
            AVNumberOfChannelsKey: 1, AVEncoderBitRateKey: 32000])
        try file?.write(from: buffer)
        file = nil
        let chunk = try QueueStore.seal(journal, duration: 1)
        let manager = UploadManager.shared
        manager.configurationChanged()
        manager.activate()
        let deadline = Date().addingTimeInterval(45)
        while Date() < deadline && FileManager.default.fileExists(atPath: chunk.manifestURL.path) {
            try await Task.sleep(for: .milliseconds(250))
        }
        XCTAssertFalse(FileManager.default.fileExists(atPath: chunk.manifestURL.path), manager.status)
        XCTAssertFalse(FileManager.default.fileExists(atPath: chunk.audioURL.path), "Delete local audio only after a durable receipt")
    }
}

import AVFoundation
import XCTest
@testable import LifeRecorder

final class RecorderTests: XCTestCase {
    @MainActor
    func testSwitchPreferenceSurvivesNewController() async {
        let old = UserDefaults.standard.object(forKey: "recorderEnabled")
        defer { UserDefaults.standard.set(old, forKey: "recorderEnabled") }
        UserDefaults.standard.set(false, forKey: "recorderEnabled")
        let off = Recorder()
        await off.resumeIfEnabled()
        XCTAssertFalse(off.enabled)
        XCTAssertFalse(off.recording)
        UserDefaults.standard.set(true, forKey: "recorderEnabled")
        let on = Recorder()
        XCTAssertTrue(on.enabled)
        XCTAssertFalse(on.recording, "Constructing a controller must not start the microphone in a background launch")
        await on.setEnabled(false)
        XCTAssertFalse(Recorder().enabled)
    }

    func testContinuousBuffersRotateIntoDecodableAACWithoutLosingFrames() async throws {
        let before = Set(QueueStore.pending().map(\.id))
        let lock = NSLock()
        var errors: [String] = []
        let writer = ChunkWriter(onChunk: {}, onError: { message in
            lock.lock(); errors.append(message); lock.unlock()
        })
        let format = AVAudioFormat(standardFormatWithSampleRate: 16000, channels: 1)!
        let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: 1600)!
        buffer.frameLength = 1600
        for i in 0..<1600 { buffer.floatChannelData![0][i] = Float(sin(Double(i) * 2 * .pi * 440 / 16000)) * 0.1 }
        for _ in 0..<1220 { writer.consume(buffer) } // 122 s, three files, no microphone required.
        await writer.finish()
        XCTAssertTrue(errors.isEmpty, errors.joined(separator: "; "))
        let chunks = QueueStore.pending().filter { !before.contains($0.id) }
        defer { for chunk in chunks { try? QueueStore.removeAcknowledged(chunk) } }
        XCTAssertEqual(chunks.count, 3)
        XCTAssertEqual(chunks.reduce(0) { $0 + $1.duration }, 122, accuracy: 0.001)
        var decodedFrames: Int64 = 0
        for chunk in chunks {
            XCTAssertEqual(try QueueStore.checksum(chunk.audioURL), chunk.sha256)
            let file = try AVAudioFile(forReading: chunk.audioURL)
            decodedFrames += file.length
        }
        XCTAssertEqual(Double(decodedFrames) / 16000, 122, accuracy: 0.1)
        XCTAssertEqual(chunks[1].startedAt.timeIntervalSince(chunks[0].startedAt), 60, accuracy: 0.001)
        XCTAssertEqual(chunks[2].startedAt.timeIntervalSince(chunks[1].startedAt), 60, accuracy: 0.001)
    }

    func testUnfinishedButDecodableFileIsRecoveredAfterRestart() async throws {
        let journal = RecordingJournal(id: UUID(), startedAt: Date())
        let name = journal.id.uuidString.lowercased()
        let path = QueueStore.directory.appendingPathComponent(name + ".m4a")
        let journalPath = QueueStore.directory.appendingPathComponent(name + ".recording.json")
        let format = AVAudioFormat(standardFormatWithSampleRate: 16000, channels: 1)!
        let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: 16000)!
        buffer.frameLength = 16000
        for i in 0..<16000 { buffer.floatChannelData![0][i] = 0 }
        try JSONEncoder().encode(journal).write(to: journalPath, options: .atomic)
        var file: AVAudioFile? = try AVAudioFile(forWriting: path, settings: [
            AVFormatIDKey: kAudioFormatMPEG4AAC, AVSampleRateKey: 16000,
            AVNumberOfChannelsKey: 1, AVEncoderBitRateKey: 32000])
        try file?.write(from: buffer)
        file = nil
        XCTAssertFalse(QueueStore.pending().contains { $0.id == journal.id })
        _ = await QueueStore.recoverInterruptedFiles()
        let chunk = try XCTUnwrap(QueueStore.pending().first { $0.id == journal.id })
        XCTAssertEqual(chunk.duration, 1, accuracy: 0.1)
        XCTAssertFalse(FileManager.default.fileExists(atPath: journalPath.path))
        try QueueStore.removeAcknowledged(chunk)
    }
}
